import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/docker/best-practices.html","title":"Best Practices","lang":"en-US","frontmatter":{},"git":{"updatedTime":1659937463000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/Noei"}],"changelog":[{"hash":"dd8d6705d634f8b654d9edf3d1015b2048e43da1","time":1659937463000,"email":"logmanxsa@gmail.com","author":"Noei","message":"Add docker content, Other content"}]},"filePathRelative":"docker/best-practices.md"}`),a={name:`best-practices.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="best-practices" tabindex="-1"><a class="header-anchor" href="#best-practices"><span>Best Practices</span></a></h1><ol><li>Prefer minimal base images <ul><li>Prefer Distroless images</li></ul></li><li>Least privilege user <ul><li>create a dedicated user and group on the image, with minimal permissions to run the application</li></ul></li><li>User Copy instead of ADD <ul><li>ADD could result in MITM attacks, sources of malicious data</li></ul></li><li>Don&#39;t leak sensitive data to Docker images <ul><li>Separate sensitive data out of application source cvode and keep them in Valut, hence, docker build phase won&#39;t contains any sensitive data</li></ul></li><li>Don&#39;t Use the latest tags <ul><li>Docker image owners should not use the lastest image tags, which may result in application breaking changes if the last image tags would not compatible with the application <br> e.g. FROM kubeops:8-alpine -&gt; &lt;version&gt;-&lt;operating system&gt;</li></ul></li><li>Use labels for matadata Labels with matadata for images provide useful information for users</li></ol>`,2)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};